#pragma once
#include <Arduino.h>
static const uint8_t EMU01_PAYLOAD_VERSION=2; static const size_t EMU01_PAYLOAD_SIZE=46;
enum Emu01Validity:uint16_t{VALID_SOIL=1u<<0,VALID_UV=1u<<1,VALID_BAROMETER=1u<<2,VALID_VEML7700=1u<<3,VALID_OPT3001=1u<<4,VALID_ENVIRONMENT=1u<<5,VALID_RAIN=1u<<6};
struct Emu01Sample{uint32_t sequence=0,uptime_ms=0;uint16_t soil_moisture_x100=0;int16_t soil_temperature_x100=0;uint16_t uv_index_x100=0;uint32_t barometer_pressure_pa=0;int16_t barometer_temperature_x100=0;uint32_t light_veml_lux_x100=0,light_opt_lux_x100=0;int16_t environment_temperature_x100=0;uint16_t environment_humidity_x100=0;uint32_t environment_pressure_pa=0,environment_gas_ohm=0;uint8_t rain_wet=0;uint16_t battery_mv=0,validity=0;};
static inline void putU16BE(uint8_t*b,size_t i,uint16_t v){b[i]=v>>8;b[i+1]=v;} static inline void putI16BE(uint8_t*b,size_t i,int16_t v){putU16BE(b,i,(uint16_t)v);} static inline void putU32BE(uint8_t*b,size_t i,uint32_t v){b[i]=v>>24;b[i+1]=v>>16;b[i+2]=v>>8;b[i+3]=v;}
static inline void packPayloadV2(const Emu01Sample&s,uint8_t out[EMU01_PAYLOAD_SIZE]){memset(out,0,EMU01_PAYLOAD_SIZE);out[0]=2;putU32BE(out,1,s.sequence);putU32BE(out,5,s.uptime_ms);putU16BE(out,9,s.soil_moisture_x100);putI16BE(out,11,s.soil_temperature_x100);putU16BE(out,13,s.uv_index_x100);putU32BE(out,15,s.barometer_pressure_pa);putI16BE(out,19,s.barometer_temperature_x100);putU32BE(out,21,s.light_veml_lux_x100);putU32BE(out,25,s.light_opt_lux_x100);putI16BE(out,29,s.environment_temperature_x100);putU16BE(out,31,s.environment_humidity_x100);putU32BE(out,33,s.environment_pressure_pa);putU32BE(out,37,s.environment_gas_ohm);out[41]=s.rain_wet?1:0;putU16BE(out,42,s.battery_mv);putU16BE(out,44,s.validity);}
